      const retainedHeight = instance.getVirtualizedHeight();
      inspectFile(instance).renderRange = createRenderRange(
        metrics.hunkLineCount
      );
      inspectFile(instance).code = createMeasuredFileCode(
        '1',
        () => metrics.lineHeight
