  test('clears measured file-level annotation height when annotations change', () => {
    const { cleanup } = installFakeHTMLElement();
    try {
      const instance = new VirtualizedFileDiff({}, virtualizer, metrics);
      const fileDiff = createTwoHunkDiff();

