    inspect(instance).cache.fileAnnotationHeight = 25;
    inspect(instance).cache.measuredHeightDeltaTotal = 25;
    instance.height = 351;

    const range = inspect(instance).computeRenderRangeFromWindow(fileDiff, 0, {
      top: metrics.diffHeaderHeight + 1,
