        strippedDeletions[pair + (additionsAreLonger ? 0 : offset)],
        strippedAdditions[pair + (additionsAreLonger ? offset : 0)]
      );
    }
    if (offset === 0) {
      bestScore = score + pairCount * MIN_IMPROVEMENT_PER_PAIR;
    } else if (score > bestScore) {
      bestScore = score;
      bestOffset = offset;
    }
  }
  if (bestOffset === 0) {
    return null;
  }

