      onChange: (event) => changedFiles.push(event.file),
    });

    try {
      instance.render({
        fileDiff: externalDiff,
        fileContainer,
        forceRender: true,
      });
      editor.edit(instance);

      await waitFor(() => editor.getText() === 'alpha\nnew value\nomega\n', {
        timeout: 4_000,
      });
      editor.applyEdits([
        {
          range: {
            start: { line: 1, character: 0 },
            end: { line: 1, character: 9 },
