      consoleError.mockRestore();
    }
  });

  test('ignores hunk-looking patch metadata before unified file headers', () => {
    const result = parsePatchFiles(
      [
        'Patch metadata mentions @@ -1 +1 @@ before the file header.\n',
        '@@ -1 +1 @@ is here.\n',
        '\n',
        '--- metadata.txt\n',
        '+++ metadata.txt\n',
        '@@ -1 +1 @@\n',
        '-old line\n',
        '+new line\n',
      ].join(''),
      undefined,
      true
    );

    expect(result[0]?.patchMetadata).toBe(
      'Patch metadata mentions @@ -1 +1 @@ before the file header.\n@@ -1 +1 @@ is here.\n\n'
    );
    expect(result[0]?.files).toHaveLength(1);
    expect(result[0]?.files[0]?.name).toBe('metadata.txt');
  });

  test('parses deleted SQL comment lines as hunk content in unified patches', () => {
    const result = parsePatchFiles(
      [
        '--- sql/test.sql\n',
        '+++ sql/test.sql\n',
        '@@ -1,5 +1,4 @@\n',
        ' -- This is a test sql file\n',
        '--- This is an sql comment\n',
        ' \n',
        ' CREATE TABLE users (\n',
        ' id BIGSERIAL PRIMARY KEY,\n',
      ].join(''),
      undefined,
      true
    );

    const file = result[0]?.files[0];
    expect(result[0]?.files).toHaveLength(1);
    expect(file?.name).toBe('sql/test.sql');
    expect(file?.deletionLines).toEqual([
      '-- This is a test sql file\n',
      '-- This is an sql comment\n',
      '\n',
      'CREATE TABLE users (\n',
      'id BIGSERIAL PRIMARY KEY,\n',
    ]);
    expect(file?.additionLines).toEqual([
      '-- This is a test sql file\n',
      '\n',
      'CREATE TABLE users (\n',
      'id BIGSERIAL PRIMARY KEY,\n',
    ]);
  });

  test('does not split hunk content that resembles unified file headers', () => {
    const result = parsePatchFiles(
      [
        '--- markers.txt\n',
        '+++ markers.txt\n',
        '@@ -1 +1 @@\n',
        '--- old marker\n',
        '+++ new marker\n',
      ].join(''),
      undefined,
      true
    );

    const file = result[0]?.files[0];
    expect(result[0]?.files).toHaveLength(1);
    expect(file?.name).toBe('markers.txt');
    expect(file?.deletionLines).toEqual(['-- old marker\n']);
    expect(file?.additionLines).toEqual(['++ new marker\n']);
  });

  test('preserves leading BOM characters in parsed hunk lines', () => {
    const result = parsePatchFiles(
      [
        'diff --git a/bom.txt b/bom.txt\n',
        'index 1111111..2222222 100644\n',
        '--- a/bom.txt\n',
        '+++ b/bom.txt\n',
        '@@ -1 +1 @@\n',
        '-\uFEFFold\n',
        '+\uFEFFnew\n',
      ].join('')
    );

    const file = result[0]?.files[0];
    expect(file?.deletionLines[0]).toBe('\uFEFFold\n');
    expect(file?.additionLines[0]).toBe('\uFEFFnew\n');
  });

  test('preserves lone surrogate characters in parsed hunk lines', () => {
    const result = parsePatchFiles(
      [
        'diff --git a/surrogate.txt b/surrogate.txt\n',
        'index 1111111..2222222 100644\n',
        '--- a/surrogate.txt\n',
        '+++ b/surrogate.txt\n',
        '@@ -1 +1 @@\n',
        '-old\ud800\n',
        '+new\ud800\n',
      ].join('')
    );

    const file = result[0]?.files[0];
    expect(file?.deletionLines[0]).toBe('old\ud800\n');
    expect(file?.additionLines[0]).toBe('new\ud800\n');
  });

  test.each([
    ['a/sp ace.ts b/sp ace.ts', 'sp ace.ts', 'sp ace.ts'],
    ['a/日本語.ts b/日本語.ts', '日本語.ts', '日本語.ts'],
    [
      String.raw`a/literal\303.ts b/literal\303.ts`,
      String.raw`literal\303.ts`,
      String.raw`literal\303.ts`,
    ],
    [String.raw`"a/\303\274ber.ts" "b/\303\274ber.ts"`, 'über.ts', 'über.ts'],
    [String.raw`"a/\303\274ber.ts" b/sp ace.ts`, 'über.ts', 'sp ace.ts'],
    [String.raw`a/sp ace.ts "b/\303\274ber.ts"`, 'sp ace.ts', 'über.ts'],
    [
      String.raw`"a/a/\303\274ber.ts" "b/b/\303\274ber.ts"`,
      'a/über.ts',
      'b/über.ts',
    ],
    [
      String.raw`"a/old\" b/inside.ts" "b/new\"name.ts"`,
      'old" b/inside.ts',
      'new"name.ts',
    ],
    ['"a/ leading.ts " "b/ trailing.ts "', ' leading.ts ', ' trailing.ts '],
  ])('reads Git header paths %s', (paths, prevName, name) => {
    const file = processFile(`diff --git ${paths}\nsimilarity index 100%\n`, {
      throwOnError: true,
    });
    expect(file?.name).toBe(name);
    expect(file?.prevName).toBe(prevName === name ? undefined : prevName);
    expect(file?.hunks).toEqual([]);
  });

  test('decodes quoted Git file headers before removing one prefix', () => {
    const file = processFile(
      [
        'diff --git a/fallback.ts b/fallback.ts\n',
        'similarity index 80%\n',
        String.raw`--- "a/a/\303\274ber.ts"` + '\n',
        String.raw`+++ "b/b/\303\274ber.ts"` + '\n',
        '@@ -1 +1 @@\n-old\n+new\n',
      ].join(''),
      { throwOnError: true }
    );
    expect(file?.prevName).toBe('a/über.ts');
    expect(file?.name).toBe('b/über.ts');
    expect(file?.deletionLines).toEqual(['old\n']);
    expect(file?.additionLines).toEqual(['new\n']);
  });

  test('decodes multiple unified files with timestamps and literal directories', () => {
    const patch = [
      String.raw`--- "a/\303\274ber.ts"` + '\told timestamp\n',
      String.raw`+++ "b/\303\274ber.ts"` + '\tnew timestamp\n',
      '@@ -1 +1 @@\n-old\n+new\n',
      '--- sp ace.ts\told timestamp\n',
      '+++ sp ace.ts\tnew timestamp\n',
      '@@ -1 +1 @@\n-before\n+after\n',
    ].join('');
    const files = parsePatchFiles(patch, undefined, true)[0]?.files;
    expect(
      files?.map(({ name, prevName, type }) => ({ name, prevName, type }))
    ).toEqual([
      { name: 'b/über.ts', prevName: 'a/über.ts', type: 'rename-changed' },
      { name: 'sp ace.ts', prevName: undefined, type: 'change' },
    ]);
  });

  test.each(['rename', 'copy'])(
    'decodes %s metadata without stripping real directories',
    (kind) => {
      const file = processFile(
        [
          'diff --git a/fallback-old.ts b/fallback-new.ts\n',
          'similarity index 100%\n',
          `${kind} from ` + String.raw`"a/\303\274ber.ts"` + '\n',
          `${kind} to ` + String.raw`"b/new\"name.ts"` + '\n',
        ].join(''),
        { throwOnError: true }
      );
      expect(file?.prevName).toBe('a/über.ts');
      expect(file?.name).toBe('b/new"name.ts');
      expect(file?.type).toBe('rename-pure');
      expect(file?.hunks).toEqual([]);
    }
  );

  test.each(['new', 'deleted'])(
    'keeps /dev/null absent for a quoted %s file',
    (type) => {
      const added = type === 'new';
      const file = processFile(
        [
          String.raw`diff --git "a/\303\274ber.ts" "b/\303\274ber.ts"` + '\n',
          `${added ? 'new' : 'deleted'} file mode 100644\n`,
          added ? '--- /dev/null\n' : String.raw`--- "a/\303\274ber.ts"` + '\n',
          added ? String.raw`+++ "b/\303\274ber.ts"` + '\n' : '+++ /dev/null\n',
          added ? '@@ -0,0 +1 @@\n+new\n' : '@@ -1 +0,0 @@\n-old\n',
        ].join(''),
        { throwOnError: true }
      );
      expect(file?.name).toBe('über.ts');
      expect(file?.prevName).toBeUndefined();
      expect(file?.type).toBe(type);
    }
  );

  test.each([
    ['old mode 100644\nnew mode 100755\n', 'change'],
    [
      'new file mode 100644\nBinary files /dev/null and b/filename differ\n',
      'new',
    ],
  ] as const)(
    'decodes a hunkless Git file with metadata %j',
    (metadata, type) => {
      const file = parsePatchFiles(
        String.raw`diff --git "a/\303\274ber.ts" "b/\303\274ber.ts"` +
          '\n' +
          metadata,
        undefined,
        true
      )[0]?.files[0];
      expect(file?.name).toBe('über.ts');
      expect(file?.type).toBe(type);
      expect(file?.hunks).toEqual([]);
    }
  );

  test('compares decoded unified names and keeps malformed quoted tokens intact', () => {
    const file = processFile(
      [
        String.raw`--- "\303\274ber.ts"` + '\n',
        '+++ über.ts\n',
        '@@ -1 +1 @@\n-old\n+new\n',
      ].join(''),
      { throwOnError: true }
    );
    expect(file?.name).toBe('über.ts');
    expect(file?.prevName).toBeUndefined();
    expect(file?.type).toBe('change');

    const malformed = processFile(
      [
        String.raw`--- "bad\q.ts"` + '\n',
        String.raw`+++ "bad\q.ts"` + '\n',
        '@@ -1 +1 @@\n-old\n+new\n',
      ].join(''),
      { throwOnError: true }
    );
    expect(malformed?.name).toBe(String.raw`"bad\q.ts"`);
  });

  test('parses quoted git diff headers with escaped file names', () => {
    const oldName =
      'test/integration/image-optimizer/app/public/\\303\\244\\303\\266\\303\\274\\305\\241\\304\\215\\305\\231\\303\\255.png';
    const newName =
      'test/e2e/image-optimizer/app/public/\\303\\244\\303\\266\\303\\274\\305\\241\\304\\215\\305\\231\\303\\255.png';
    const file = processFile(
      [
        `diff --git "a/${oldName}" "b/${newName}"\n`,
        'similarity index 100%\n',
      ].join(''),
      { isGitDiff: true }
    );

    expect(file?.name).toBe('test/e2e/image-optimizer/app/public/äöüščří.png');
    expect(file?.prevName).toBe(
      'test/integration/image-optimizer/app/public/äöüščří.png'
    );
    expect(file?.type).toBe('rename-pure');
  });

  test(
    'splitLineCount should match rendered line count in split mode',
    async () => {
      for (const patch of result) {
        for (const file of patch.files) {
          if (file.hunks.length === 0) continue;

          const renderer = new DiffHunksRenderer({ diffStyle: 'split' });
          const renderResult = await renderer.asyncRender(file);
          // Split mode: both columns have the same visual height due to a
          // combination of lines and empty buffer regions.  Line types will be a
          // mix of context, additions and deletions.  Lets make sure what we
          // math from parsePatchFiles is correctly rendered and vice versa.
          const expectedSplitRows = file.hunks.reduce(
            (sum, hunk) => sum + hunk.splitLineCount,
            0
          );
          expect(expectedSplitRows).toBe(countSplitRows(renderResult));
        }
      }
    },
    { timeout: 15000 }
  );

  test(
    'unifiedLineCount should match rendered line count in unified mode',
    async () => {
      for (const patch of result) {
        for (const file of patch.files) {
          if (file.hunks.length === 0) continue;
          const renderer = new DiffHunksRenderer({ diffStyle: 'unified' });
          const { unifiedContentAST } = await renderer.asyncRender(file);
          assertDefined(
            unifiedContentAST,
            'unifiedContentAST should be defined'
          );
          // In 'unified' style we stack all output as context, deletions,
          // additions. Lets ensure we are mathing correctly and rendering to
          // this math
          const expectedUnifiedLines = file.hunks.reduce(
            (sum, hunk) => sum + hunk.unifiedLineCount,
            0
          );
          expect(expectedUnifiedLines).toBe(
            countRenderedLines(unifiedContentAST)
          );
        }
      }
    },
    { timeout: 15000 }
  );
});

