  test('preserves lone surrogate characters in parsed hunk lines', () => {
    const result = parsePatchFiles(
      [
        'diff --git a/surrogate.txt b/surrogate.txt\n',
        'index 1111111..2222222 100644\n',
        '--- a/surrogate.txt\n',
        '+++ b/surrogate.txt\n',
