    ],
  ] as const)(
    'decodes a hunkless Git file with metadata %j',
    (metadata, type) => {
      const file = parsePatchFiles(
        String.raw`diff --git "a/\303\274ber.ts" "b/\303\274ber.ts"` +
          '\n' +
