      ]);
      expect(hunk.hunkSpecs).toBe('@@ -1,6 +1,6 @@\n');
      expect(getTotalLineCountFromHunks(file.hunks)).toBe(4);
      expect(verifyPatchHunkValues(result).errors).toEqual([]);
    } finally {
      consoleError.mockRestore();
