import { DiffHunksRenderer } from '../src/renderers/DiffHunksRenderer';
import { composeCacheKey } from '../src/utils/composeCacheKey';
import { getTotalLineCountFromHunks } from '../src/utils/getTotalLineCountFromHunks';
import {
  parsePatchFiles,
  processFile,
  processPatch,
} from '../src/utils/parsePatchFiles';
import {
  diffPatch,
  finalBlankLinePatch,
  formatPatchWithVersionTrailer,
  malformedPatch,
} from './mocks';
import {
  assertDefined,
  countRenderedLines,
  countSplitRows,
  patchDigest,
  verifyPatchHunkValues,
} from './testUtils';

afterAll(async () => {
  await disposeHighlighter();
});

const issue1094Patch = [
  '--- f\n',
  '+++ f\n',
  '@@ -1,6 +1,6 @@\n',
  '-a\n',
  '+A\n',
  ' c0\n',
  ' c1\n',
  '-b\n',
  '+B\n',
].join('');

const validIssue1094Patch = issue1094Patch.replace(
  '@@ -1,6 +1,6 @@',
  '@@ -1,4 +1,4 @@'
);

function createFilePatch(name: string): string {
  return [
    `diff --git a/${name} b/${name}\n`,
    'index 1111111..2222222 100644\n',
    `--- a/${name}\n`,
    `+++ b/${name}\n`,
    '@@ -1 +1 @@\n',
    '-old\n',
    '+new\n',
  ].join('');
}

