);

function createFilePatch(name: string): string {
  return [
    `diff --git a/${name} b/${name}\n`,
    'index 1111111..2222222 100644\n',
    `--- a/${name}\n`,
    `+++ b/${name}\n`,
    '@@ -1 +1 @@\n',
    '-old\n',
    '+new\n',
  ].join('');
}

describe('parsePatchFiles', () => {
  const result = parsePatchFiles(diffPatch);
