  const themeNames = themeInfo.map(({ id }) => id).sort();
  assert.deepEqual(
    readdirSync(new URL('../themes/', import.meta.url))
      .filter((file) => file.endsWith('.json'))
      .map((file) => file.slice(0, -5))
