      'try { throw e } catch (e) {} finally {}\n' +
      "import x from 'm'; export default x;\n" +
      'async function g() { await g() }\n' +
      "new X(); delete a.b; typeof x; a instanceof X; 'k' in a; void 0;\n" +
      'class C {} const c = 1; let l; var v; yield 1;',
    { theme: bucketTheme }
  );
  for (const [word, color] of [
    ['if', '#000002'],
    ['else', '#000002'],
    ['switch', '#000002'],
    ['case', '#000002'],
    ['default', '#000002'],
    ['for', '#000002'],
    ['while', '#000002'],
    ['do', '#000002'],
    ['return', '#000002'],
    ['try', '#000002'],
    ['throw', '#000002'],
    ['catch', '#000002'],
    ['finally', '#000002'],
    ['await', '#000002'],
    ['yield', '#000002'],
    ['import', '#000006'],
    ['export', '#000006'],
    ['function', '#000003'],
    ['class', '#000003'],
    ['const', '#000003'],
    ['let', '#000003'],
    ['var', '#000003'],
    ['async', '#000001'],
