      ['string', 'type.jsdoc'],
      ['}', 'punctuation.bracket'],
      ['key', 'variable.jsdoc'],
      ['- the key', 'comment.doc'],
      ['*', 'comment.doc'],
      ['@returns', 'keyword.jsdoc'],
      ['{', 'punctuation.bracket'],
      ['Promise<boolean>', 'type.jsdoc'],
      ['}', 'punctuation.bracket'],
      ['done', 'comment.doc'],
      ['*', 'comment.doc'],
      ['@template', 'keyword.jsdoc'],
      ['T', 'variable.jsdoc'],
      ['*', 'comment.doc'],
      ['@deprecated', 'keyword.jsdoc'],
      ['use other', 'comment.doc'],
      ['*/', 'comment.doc'],
    ]
  );
});

