      const funcs: { name: string; body: string }[] = [];
      const starts = [...text.matchAll(/^\s*\(func(?:\s+(\$[^\s()]+))?/gm)];
      for (const [i, m] of starts.entries()) {
        const end = starts[i + 1]?.index ?? text.length;
        funcs.push({
          name: m[1] ?? `#${i + imported}`,
          body: text.slice(m.index, end).replace(/"(?:[^"\\]|\\.)*"/g, '""'),
