});

void test('preprocessor: language registration rejects ambiguous or malformed entries', () => {
  for (const body of [
    '(language "js" $f "js")',
    '(language "js" $f "shared") (language "ts" $g "shared")',
    '(language "js" $f "ts") (language "ts" $g)',
  ]) {
    assert.throws(
      () => synthetic(`(language-table ${body})`),
      /Duplicate language name/
    );
  }
  for (const [body, message] of [
    ['(entry "js" $f)', /expects language entries/],
    ['(language JS $f)', /canonical language name/],
    ['(language "JS" $f)', /canonical language name/],
    ['(language "js")', /needs a lexer function/],
    ['(language "js" 42)', /needs a lexer function/],
    ['(language "js" $f "JavaScript")', /Invalid language alias/],
    ['(language "js" $f "two words")', /Invalid language alias/],
  ] as const) {
    assert.throws(() => synthetic(`(language-table ${body})`), message);
  }
  assert.throws(
    () =>
      synthetic(`
    (language-table (language "js" $f))
    (language-table (language "ts" $g))`),
    /Duplicate language-table/
  );
  assert.throws(
    () =>
      synthetic(`
    (enum $Language "js")
    (language-table (language "ts" $g))`),
    /Duplicate enum/
  );
});

void test('preprocessor: language IDs fit the control byte and partial fixtures need no table', () => {
  const entries = Array.from(
    { length: 257 },
    (_, i) => `(language "l${i}" $f)`
  );
  const full = synthetic(`(language-table ${entries.slice(0, 256).join(' ')})`);
  assert.equal(full.languages.l255, 255);
  assert.throws(
    () => synthetic(`(language-table ${entries.join(' ')})`),
    /1–256 languages/
  );
  assert.throws(() => synthetic('(language-table )'), /1–256 languages/);
  const partial = synthetic('(enum $Local "a")');
  assert.deepEqual(partial.languages, {});
  assert.throws(
    () => generateLanguages(partial.languages),
    /no language-table/
  );
});

void test('preprocessor: stream lexers must branch by label name', () => {
  const lexer = (labels: string) => `
    (func $hlRust
      (local $x i32) (local $i i32)
      (call $lexEmitLeadingContinuation)
      (block $outer
        (block $inner (br_table ${labels} (local.get $i)))
        (local.set $x (i32.const 0)))
      (block $done
        (loop $l
          (local.set $i (i32.add (local.get $i) (local.get $x)))
          (br_if $done (i32.gt_u (local.get $i) (i32.const 10)))
          (br $l))))`;
  const named = synthetic(lexer('$outer $inner')).code;
  assert.match(named, /i32\.load offset=\d+ \(local\.get \$streamRoot\)/);
  assert.throws(() => synthetic(lexer('1 0')), /branch by index/);
});

void test('preprocessor: a nested block may shadow an outer label', () => {
  const { code } = synthetic(`
    (func $hlRust
      (local $x i32)
      (call $lexEmitLeadingContinuation)
      (block $a
        (br_if $a (local.get $x))
        (block $a (br $a))
        (local.set $x (i32.const 1))))`);
  wat2wasm(preludeUrl.pathname, code);
});

void test('preprocessor: data segments count UTF-8 bytes', () => {
  assert.throws(
    () =>
      synthetic(`
        (data (i32.const 100) "éé")
        (data (i32.const 102) "x")`),
    /overlap/
  );
  synthetic(`
    (data (i32.const 100) "éé")
    (data (i32.const 104) "x")`);
});

void test('preprocessor: the $Token enum cannot outgrow the emitter regions', () => {
  const names = (n: number) =>
    Array.from({ length: n }, (_, i) => `"t${i}"`).join(' ');
  const { enumMap } = synthetic(`(enum $Token ${names(74)})`);
  assert.throws(() => listTokenTypes(enumMap), /span cache holds 73/);
  const { enumMap: ok } = synthetic(`(enum $Token ${names(73)})`);
  assert.equal(listTokenTypes(ok).length, 73);
});

